WITH posts AS ( SELECT CASE WHEN q.IS_NOTICE = 'Y' THEN 'NOTICE' ELSE 'QNA' END AS postType, q.QNA_NO AS postNo, q.QNA_TITLE AS title, q.QNA_CTT AS content, q.USER_ID AS userId, u.USER_NAME AS writerName, u.ROLE AS writerRole, TO_CHAR(q.QNA_CREATED, 'YYYY-MM-DD') AS createdAtStr, NVL(q.QNA_HIT,0) AS hit, q.QNA_STATUS AS qnaStatus, q.IS_NOTICE AS isNotice, q.ANS_CTT AS ansCtt, TO_CHAR(q.ANS_AT, 'YYYY-MM-DD') AS ansAtStr, CAST(NULL AS NUMBER) AS reviewRating, CAST(NULL AS VARCHAR2(50)) AS orderNo FROM QNA_BOARD q JOIN USERS u ON u.USER_ID = q.USER_ID
UNION ALL
SELECT 'REVIEW' AS postType, r.REVIEW_NO AS postNo, r.REVIEW_TITLE AS title, r.REVIEW_CTT AS content, r.USER_ID AS userId, u.USER_NAME AS writerName, u.ROLE AS writerRole, TO_CHAR(r.REVIEW_CREATED, 'YYYY-MM-DD') AS createdAtStr, NVL(r.REVIEW_HIT,0) AS hit, CAST(NULL AS VARCHAR2(20)) AS qnaStatus, CAST(NULL AS VARCHAR2(1)) AS isNotice, CAST(NULL AS VARCHAR2(4000)) AS ansCtt, CAST(NULL AS VARCHAR2(20)) AS ansAtStr, r.REVIEW_RATING AS reviewRating, r.ORDER_NO AS orderNo FROM REVIEW_BOARD r JOIN USERS u ON u.USER_ID = r.USER_ID ) SELECT * FROM posts WHERE postType = #{postType} AND postNo = #{postNo}

mapper.update:
UPDATE QNA_BOARD
SET
  DEL_YN = 'Y',         
  DEL_AT = SYSDATE,     
  DEL_BY = #{adminId}   
WHERE QNA_NO = #{postNo}

UPDATE REVIEW_BOARD
SET
  DEL_YN = 'Y',         
  DEL_AT = SYSDATE,     
  DEL_BY = #{adminId}   
WHERE REVIEW_NO = #{postNo}
